SELECT a.id, a.fd_enter_type_code, a.fd_name, a.fd_card_no, a.enter_factory, a.enter_factory_code, a.enter_start_time, a.enter_end_time, a.fd_img, a.is_delete, a.fd_filing_id, a.fd_per_phone, DATE_FORMAT(a.issuance_time,'%Y-%m-%d %H:%i:%s') issuance_time, a.issuance_result, a.create_by, DATE_FORMAT(a.create_time,'%Y-%m-%d %H:%i:%s') create_time, a.update_by, DATE_FORMAT(a.update_time,'%Y-%m-%d %H:%i:%s') update_time FROM safety_enter_issuance a WHERE 1=1
order by a.create_time desc
limit #{offset}, #{limit}
limit #{limit}
limit 5000
